--
-- Table structure for table `paper_number`
--

CREATE TABLE `paper_number` (
  `id` int(11) NOT NULL,
  `paper_name_bn` varchar(506) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `paper_name_en` varchar(506) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `create_by` int(11) DEFAULT NULL,
  `update_by` int(11) DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `created_at` varchar(506) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `updated_at` varchar(506) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deleted_at` varchar(506) COLLATE utf8mb4_unicode_ci DEFAULT NULL
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

